// Map single-character type codes to icon descriptors.
// T/A = tank ally, t/E = tank enemy, P = aircraft ally, p = aircraft enemy,
// O = objective, F = airfield, B = bomb point, R = respawn, N = unknown.
static const lv_image_dsc_t * icon_for_type(char c) {
    switch (c) {
        case 'A': case 'T': return &icon_tank_ally_dsc;
        case 'E': case 't': return &icon_tank_enemy_dsc;
        case 'P':           return &icon_aircraft_ally_dsc;
        case 'p':           return &icon_aircraft_enemy_dsc;
        case 'O':           return &icon_objective_dsc;
        case 'F':           return &icon_airfield_dsc;
        case 'B':           return &icon_bomb_point_dsc;
        case 'R':           return &icon_respawn_dsc;
        default:            return &icon_unknown_dsc;
    }
}
